import{z as s,x as n,o as e,c as p,q as o,j as B,D as E,d as t,s as i,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"虚拟计量","description":"","frontmatter":{"title":"虚拟计量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/virtual-metrology.md","filePath":"litho/virtual-metrology.md","lastUpdated":1791413859000}'),d={name:"litho/virtual-metrology.md"};function h(m,a,C,D,M,V){const l=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="虚拟计量" tabindex="-1">虚拟计量 <a class="header-anchor" href="#虚拟计量" aria-label="Permalink to &quot;虚拟计量&quot;">​</a></h1><div class="epigraph"><p>虚拟计量用设备与上游数据估计本步 CD 或套刻，给 R2R 充样本；它估计的是相关，不是第二台 SEM，更不能当法律放行。</p><footer>—— 对照半导体虚拟计量（VM）与 APC 的公开讨论；IEEE 半导体生产中的 VM 传统</footer></div><p><a href="/litho/fab-data-loop">上一课</a>把数据对齐写清。缺口是抽样墙：不能每片 SEM。<a href="/litho/ml-hotspot-prediction">ML 热点</a> 已限制学习模型做排序；本课钉过程控制里的虚拟计量（virtual metrology）。良率模型从下一课开始，不再扩控制环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VM：用轨迹传感器、胶厚、光源功率、上游 AEI 等，回归本层 CD/套刻，供 APC 在缺测片上更新。好处：节拍变快、边缘片也有估计。风险：漂移（换胶、保养后相关破裂）、外推（新产品开口率）、以及把 VM 当放行——分派必须用真实计量或明确的降级规则。</p><p><span class="marginnote">「虚拟计量」就是不用尺子、只拿生产自带的数据（功率、胶厚、上游测量）去「猜」这一片的 CD 或套刻——像不量体温、靠心率和出汗估发烧，快，但有误差，关键决定还得靠真体温计。</span></p><p>缺口是<strong>角色</strong>，不是网络结构。VM 进反馈要当「带较大方差的观测」，Kalman/EWMA 降权；当真理会让环在模型里自嗨。</p><h3 id="相关不是因果" tabindex="-1">相关不是因果 <a class="header-anchor" href="#相关不是因果" aria-label="Permalink to &quot;相关不是因果&quot;">​</a></h3><p>胶厚与 CD 相关，前馈课已经用物理模型吃过。VM 若再吃同一胶厚，等于双计。特征应是 APC 尚未用的残差信息（腔体 OES、扫描机传感器），或用于未测片的插值，并声明与前馈的正交。</p><p><span class="marginnote">保持集必须含时间外批次与保养后。只报训练 R² 的 VM 禁止进环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：与参考计量匹配后的尺度。部署：仅 APC 建议，限幅严于真值环；SPC 与放行仍用真值抽样。监控：VM 与真值差的控制图，破裂即停 VM。与 OPC：禁止用 VM 反演全芯片核。</p><p>特征表要声明哪些已被前馈使用，避免双计。IEEE 半导体生产里的 VM 传统把「软传感器」放在控制环里，同时把实验室计量留作法律量——本课沿用这道法律分界。</p><p><span class="marginnote">把 VM 想成「近视的助手」：它每片都报数但不够准；真值计量是每 N 片来一次的老医师。让助手参与但每次意见打对折（降权），老医师定期校表——这就是「降权观测」的日常含义。</span></p>',14)),(e(),B(A,null,{default:E(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22VM%20%E5%A4%84%E4%BA%8E%E4%BB%80%E4%B9%88%E7%8A%B6%E6%80%81%22%5D%20--%3E%20N%5B%22%E6%AD%A3%E5%B8%B8%EF%BC%9A%E6%AE%8B%E5%B7%AE%20SPC%20%E5%9C%A8%E6%8E%A7%22%5D%0A%20%20ST%20--%3E%20D%5B%22%E6%BC%82%E7%A7%BB%EF%BC%9A%E6%8D%A2%E8%83%B6%E6%88%96%E4%BF%9D%E5%85%BB%E5%90%8E%E7%9B%B8%E5%85%B3%E7%A0%B4%E8%A3%82%22%5D%0A%20%20ST%20--%3E%20E%5B%22%E5%A4%96%E6%8E%A8%EF%BC%9A%E6%96%B0%E4%BA%A7%E5%93%81%E8%B6%85%E5%87%BA%E8%AE%AD%E7%BB%83%E5%9F%9F%22%5D%0A%20%20N%20--%3E%20A1%5B%22%E7%BB%A7%E7%BB%AD%E7%BB%99%20R2R%20%E9%99%8D%E6%9D%83%E8%A7%82%E6%B5%8B%22%5D%0A%20%20D%20--%3E%20A2%5B%22%E5%81%9C%20VM%EF%BC%8C%E9%87%8D%E6%96%B0%E5%8C%B9%E9%85%8D%E8%AE%AD%E7%BB%83%22%5D%0A%20%20E%20--%3E%20A3%5B%22%E4%B8%8D%E8%BE%93%E5%87%BA%E4%BC%B0%E8%AE%A1%EF%BC%8C%E5%9B%9E%E9%80%80%E7%9C%9F%E5%80%BC%E6%8A%BD%E6%A0%B7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"\\(y \\approx f(x_\\mathrm{eq}, x_\\mathrm{up})\\)。当 \\(f\\) 的域（产品、机台、食谱）变，残差结构变。VM 误差通常空间相关（同一指纹盲区），会让高阶项更自信地错——比随机噪声更危险。故 VM 适合低维（均值、径向一次），禁止单独支撑场内高阶。",-1)),(e(),B(A,null,{default:E(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E8%AE%BE%E5%A4%87%20%2F%20%E4%B8%8A%E6%B8%B8%E7%89%B9%E5%BE%81%22%5D%20--%3E%20VM%5B%22%E8%99%9A%E6%8B%9F%E8%AE%A1%E9%87%8F%22%5D%0A%20%20VM%20--%3E%20APC%5B%22%E9%99%8D%E6%9D%83%E8%BF%9B%E5%85%A5%20R2R%22%5D%0A%20%20REAL%5B%22%E7%9C%9F%E5%80%BC%E6%8A%BD%E6%A0%B7%22%5D%20--%3E%20MON%5B%22VM-%E7%9C%9F%E5%80%BC%E6%AE%8B%E5%B7%AE%20SPC%22%5D%0A%20%20MON%20--%3E%20GATE%5B%22%E7%A0%B4%E8%A3%82%E5%88%99%E5%81%9C%20VM%22%5D%0A%20%20REAL%20--%3E%20DISP%5B%22%E5%88%86%E6%B4%BE%20%2F%20%E6%94%BE%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>VM 是降权观测。真值抽样的残差图一破裂就停软传感器，放行仍用 SEM / 套刻机。</p><p><span class="marginnote">常见误区：看平均值「VM 和真值差不多」就放心。VM 的错误常带同一套指纹——同一批一起错向一边，比随机噪声更骗人；平均值看不出来，必须专门盯 VM 与真值的差值图。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VM 不替代 LRC，不替代缺陷检测。不发明 arXiv。本课结束过程控制单元。</p><p>后课默认：VM 只给低维环充样本，放行用真值。下一课程用缺陷与面积谈良率，不再拧扫描机旋钮。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>虚拟计量是降权观测，不是放行计量。</li><li>与前馈特征正交，保持集含保养后。</li><li>禁止用 VM 撑场内高阶或 OPC 核。</li><li>出处：半导体 VM–APC 公开讨论；IEEE 半导体生产 VM 传统。</li></ul>',7))])}const _=s(d,[["render",h]]);export{f as __pageData,_ as default};
